// Junta as notícias de todas as fontes: fica só com as mais recentes, tira as
// repetidas e limita a quantidade por fonte, para o resumo ficar leve e atual.
const config = $('Configuração do resumo').first().json;
const limitePorFonte = Number(config.itens_por_fonte) || 6;
const desde = Date.now() - (Number(config.horas) || 24) * 60 * 60 * 1000;
const SECOES = ['Brasil', 'Mundo', 'Mercado financeiro', 'Política', 'Tecnologia e tendências'];

const limpar = (s) => String(s ?? '').replace(/\s+/g, ' ').trim();
const chave = (s) => limpar(s).toLowerCase().normalize('NFD').replace(/[^a-z0-9 ]/g, '');

const porFonte = new Map();
const falhas = new Set();
const vistos = new Set();

$input.all().forEach((item, i) => {
  const fonte = $('Fontes').itemMatching(i)?.json;
  if (!fonte) return;
  const n = item.json;
  if (n.error || !n.title) {
    if (n.error) falhas.add(fonte.fonte);
    return;
  }
  const data = Date.parse(n.isoDate || n.pubDate || '');
  if (Number.isFinite(data) && data < desde) return;
  const titulo = limpar(n.title);
  if (vistos.has(chave(titulo))) return;
  const lista = porFonte.get(fonte.fonte) ?? [];
  if (lista.length >= limitePorFonte) return;
  vistos.add(chave(titulo));
  lista.push({
    secao: fonte.secao,
    fonte: fonte.fonte,
    titulo,
    resumo: limpar(n.contentSnippet || n.content || '').slice(0, 240),
    link: limpar(n.link),
    data: Number.isFinite(data) ? new Date(data).toISOString() : '',
  });
  porFonte.set(fonte.fonte, lista);
});

const noticias = [...porFonte.values()].flat();
const texto = SECOES.map((secao) => {
  const daSecao = noticias.filter((n) => n.secao === secao);
  const linhas = daSecao.map((n) => `- [${n.fonte}] ${n.titulo}${n.resumo ? ' — ' + n.resumo : ''} (${n.link})`);
  return `## ${secao}\n${linhas.join('\n') || '(nenhuma notícia recente)'}`;
}).join('\n\n');

return [{ json: { total: noticias.length, noticias, texto, falhas: [...falhas] } }];

// Prepara o pedido para o Gemini: a data, as cotações do dia e as notícias selecionadas.
const config = $('Configuração do resumo').first().json;
const selecao = $('Selecionar notícias').first().json;
const cotacoesApi = $input.first().json ?? {};

const numero = (v) =>
  Number(v).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
function cotacao(codigo, nome) {
  const moeda = cotacoesApi[codigo];
  if (!moeda?.bid || !Number.isFinite(Number(moeda.bid))) return '';
  const variacao = Number(moeda.pctChange);
  const sinal = variacao >= 0 ? '+' : '';
  return `${nome} R$ ${numero(moeda.bid)}` + (Number.isFinite(variacao) ? ` (${sinal}${numero(variacao)}%)` : '');
}
const cotacoes = [cotacao('USDBRL', 'Dólar'), cotacao('EURBRL', 'Euro'), cotacao('BTCBRL', 'Bitcoin')]
  .filter(Boolean)
  .join(' · ');

const hoje = DateTime.now()
  .setZone(config.fuso_horario || 'America/Sao_Paulo')
  .setLocale('pt-BR')
  .toFormat("cccc, dd 'de' LLLL 'de' yyyy");

const pedido = [
  `Data: ${hoje}`,
  `Cotações: ${cotacoes || 'indisponíveis'}`,
  '',
  'Notícias (formato: - [fonte] título — trecho (link)):',
  '',
  selecao.texto,
].join('\n');

return [{ json: { pedido, cotacoes, hoje, total_noticias: selecao.total } }];

// Converte o resumo (Markdown simples) para o HTML aceito pelo Telegram e divide
// em partes (o Telegram aceita até 4096 caracteres por mensagem).
const entrada = $input.first().json;
const texto = String(
  entrada.texto ?? entrada.mergedResponse ?? (entrada.content?.parts ?? []).filter((p) => !p.thought).map((p) => p.text ?? '').join(''),
).trim();
const LIMITE = 3500;

const escapar = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

function markdownParaHtml(md) {
  // Código e links são convertidos antes e guardados, para não serem alterados depois.
  const guardados = [];
  const guardar = (html) => `\u0000${guardados.push(html) - 1}\u0000`;
  const t = md
    .replace(/```[\w+-]*\n?([\s\S]*?)```/g, (_, codigo) =>
      guardar(`<pre>${escapar(codigo.replace(/\n$/, ''))}</pre>`),
    )
    .replace(/`([^`\n]+)`/g, (_, codigo) => guardar(`<code>${escapar(codigo)}</code>`))
    .replace(/\[([^\]\n]+)\]\((https?:\/\/[^\s)]+)\)/g, (_, rotulo, url) =>
      guardar(`<a href="${escapar(url).replace(/"/g, '&quot;')}">${escapar(rotulo)}</a>`),
    );
  return escapar(t)
    .replace(/^[ \t]*#{1,6}[ \t]+(.+?)[ \t#]*$/gm, (_, titulo) => `<b>${titulo.replace(/\*\*|__/g, '')}</b>`)
    .replace(/^([ \t]*)[*+-][ \t]+/gm, '$1• ')
    .replace(/\*\*(?=\S)([^\n]*?\S)\*\*/g, '<b>$1</b>')
    .replace(/__(?=\S)([^\n]*?\S)__/g, '<b>$1</b>')
    .replace(/(^|[^\w*])\*(?=\S)([^*\n]*?\S)\*(?![\w*])/g, '$1<i>$2</i>')
    .replace(/(^|[^\w])_(?=\S)([^_\n]*?\S)_(?!\w)/g, '$1<i>$2</i>')
    .replace(/~~(?=\S)([^~\n]*?\S)~~/g, '<s>$1</s>')
    .replace(/\u0000(\d+)\u0000/g, (_, i) => guardados[Number(i)]);
}

function dividir(t, limite) {
  const partes = [];
  let resto = t;
  while (resto.length > limite) {
    let corte = resto.lastIndexOf('\n\n', limite);
    if (corte < limite / 2) corte = resto.lastIndexOf('\n', limite);
    if (corte < limite / 2) corte = resto.lastIndexOf(' ', limite);
    if (corte < limite / 2) corte = limite;
    partes.push(resto.slice(0, corte).trim());
    resto = resto.slice(corte).trim();
  }
  if (resto) partes.push(resto);
  return partes;
}

return dividir(texto || 'Não consegui montar o resumo de hoje. 😕', LIMITE).map((parte) => ({
  json: { html: markdownParaHtml(parte), texto_simples: escapar(parte) },
}));

// Plano B: se o Gemini falhar (limite do plano gratuito, por exemplo), manda os
// principais títulos de cada seção, com link, sem o resumo escrito pela IA.
const selecao = $('Selecionar notícias').first().json;
const config = $('Configuração do resumo').first().json;
const SECOES = [
  ['Brasil', '🇧🇷'],
  ['Mundo', '🌎'],
  ['Mercado financeiro', '💰'],
  ['Política', '🏛️'],
  ['Tecnologia e tendências', '💡'],
];

const partes = [`☀️ **Bom dia, ${config.nome_dono}!** Hoje não consegui escrever o resumo, então seguem os principais títulos.`];
for (const [secao, emoji] of SECOES) {
  const itens = (selecao.noticias ?? []).filter((n) => n.secao === secao).slice(0, 4);
  if (!itens.length) continue;
  partes.push(`${emoji} **${secao}**\n` + itens.map((n) => `- ${n.titulo} ([${n.fonte}](${n.link}))`).join('\n'));
}
if (partes.length === 1) partes.push('Não consegui ler as fontes de notícias hoje. 😕');

return [{ json: { texto: partes.join('\n\n') } }];
